import ast, hashlib, json, tempfile
from pathlib import Path
from unittest.mock import patch
from yoyo.evaluation import spike_burst_v3_density_rearm_report as r
source_path=Path(r.__file__)
tree=ast.parse(source_path.read_text())
imports=[]
for node in ast.walk(tree):
    if isinstance(node,ast.ImportFrom): imports.append(node.module or "")
    elif isinstance(node,ast.Import): imports.extend(a.name for a in node.names)
assert not any(name.startswith("yoyo") for name in imports)
for node in ast.walk(tree):
    if isinstance(node,ast.Call):
        name=node.func.id if isinstance(node.func,ast.Name) else node.func.attr if isinstance(node.func,ast.Attribute) else ""
        assert name not in {"detect","simulate_trade","match_signals","forward_outcome","trade_summary","early_fields"}
checks=["no_detector_or_execution_import_or_call"]
def dump(path,value):
    path.write_text(json.dumps(value))
    return r.sha(path)
def bad(call,name):
    try:call()
    except (ValueError,KeyError):checks.append(name)
    else:raise AssertionError("Accepted invalid provenance: "+name)
with tempfile.TemporaryDirectory(prefix="g-report-auth-synthetic-") as folder:
    root=Path(folder); gout=root/"g"; f=root/"f"; v1=root/"v1"
    for d in (gout,f,v1):d.mkdir()
    src=root/"source.py";src.write_text("# Synthetic immutable source\n")
    pins={"source.py":r.sha(src)}
    for d in (gout,f):(d/"labels.csv.gz").write_bytes(b"synthetic identical labels, not real market data")
    def artifact(path):return {"path":str(path),"sha256":r.sha(path)}
    fp={"status":"complete","config":{"fixture":True},"source_pins":pins,"sources":{},"artifacts":[artifact(f/"labels.csv.gz")]}
    fph=dump(f/"prepared_manifest.json",fp)
    fv={"status":"complete","config":fp["config"],"source_pins":pins,"prepared_sha":fph,"artifacts":[]}
    fvh=dump(f/"validation_manifest.json",fv)
    config=dict(schema="spike-v3-density-rearm-v1",arms=list(r.ARMS),fixed_population=r.FIXED,
                acceptance=r.THRESHOLDS,cost_bp=20,structural_hypothesis_number=7,
                prior_single_gate_explorations=13,holdout_per_new_config=1,
                production_eligible=False,training_eligible=False)
    gp={"status":"complete","config":config,"source_pins":pins,"sources":{},"artifacts":[artifact(gout/"labels.csv.gz")]}
    gph=dump(gout/"prepared_manifest.json",gp)
    gv={"status":"complete","config":config,"source_pins":pins,"prepared_sha":gph,"prior_F_validation_sha":fvh,"artifacts":[]}
    gvh=dump(gout/"validation_manifest.json",gv)
    originals={}
    for name in r.ORIGINAL_HASHES:
        p=v1/name;p.write_bytes(b"synthetic original-V1 lineage only")
        originals[name]=r.sha(p)
    patches=dict(ROOT=root,OUT=gout,F_SOURCE=f,F_PREPARED_SHA=fph,F_VALIDATION_SHA=fvh,
                 ORIGINAL=v1,ORIGINAL_HASHES=originals)
    with patch.multiple(r,**patches), patch.object(r.pd,"read_csv",side_effect=AssertionError("Authentication parsed a table")), patch.object(r.pd,"read_pickle",side_effect=AssertionError("Authentication parsed a feature")):
        a,b,refs=r.authenticate(gvh)
        assert a["config"]==config and b["prepared_sha"]==gph
        checks.append("full_synthetic_G_F_V1_lineage_without_table_parsing")
        bad(lambda:r.authenticate("not-a-sha"),"explicit_valid_sha_required")
        bad(lambda:r.authenticate("0"*64),"wrong_validation_sha_denied")
        src.write_text("# mutated")
        bad(lambda:r.authenticate(gvh),"changed_pinned_source_denied")
        src.write_text("# Synthetic immutable source\n")
        op=v1/next(iter(originals)); saved=op.read_bytes();op.write_bytes(b"mutated")
        bad(lambda:r.authenticate(gvh),"changed_original_V1_denied");op.write_bytes(saved)
        before=(gout/"labels.csv.gz").read_bytes();(gout/"labels.csv.gz").write_bytes(b"changed")
        bad(lambda:r.authenticate(gvh),"changed_frozen_labels_denied");(gout/"labels.csv.gz").write_bytes(before)
        altered=dict(gv,status="started")
        ah=dump(gout/"validation_manifest.json",altered)
        bad(lambda:r.authenticate(ah),"incomplete_G_validation_denied")
        altered=dict(gv,config=dict(config,cost_bp=10))
        ah=dump(gout/"validation_manifest.json",altered)
        bad(lambda:r.authenticate(ah),"changed_cost_or_prepare_contract_denied")
print(json.dumps({"status":"passed","checks":checks,"synthetic_only":True,"real_market_files_read":False}))
